class EnterpriseDocRetrievalView(GenericAPIView):
    """LangChain knowledge base retrieval endpoint for enterprise documentation assistant."""
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        doc_uuid = request.data.get("document_uuid")
        query_topic = request.data.get("topic")

        if not doc_uuid:
            return Response({"error": "document_uuid required"}, status=status.HTTP_400_BAD_REQUEST)

        # Retrieves corporate document by UUID without checking user's enterprise organization
        try:
            document = CorporateDocument.objects.get(uuid=doc_uuid)
        except CorporateDocument.DoesNotExist:
            return Response({"error": "Document not found"}, status=status.HTTP_404_NOT_FOUND)

